    /// Every prefab's stages are timm's, to the channel: the float32 width
    /// rule and the group rounding reproduce timm's, and every prefab
    /// lowers.
    #[test]
    fn test_prefab_stages_are_timms() {
        assert_eq!(
            TIMM_STAGES.len(),
            RegNetContractConfig::prefab_names().len()
        );
        for (name, stages) in TIMM_STAGES {
            let config = RegNetContractConfig::expect_prefab(name);
            let ours: Vec<_> = config
                .try_stages()
                .unwrap_or_else(|e| panic!("{name}: {e}"))
                .into_iter()
                .map(
                    |RegNetStage {
                         depth,
                         width,
                         mid_width,
                         groups,
                     }| (depth, width, mid_width, groups),
                )
                .collect();
            assert_eq!(ours, stages, "{name}");
            config
                .try_to_structure()
                .unwrap_or_else(|e| panic!("{name}: {e}"));
        }
    }
